def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Find all pairs (q, r) such that q+r=800, q < r, and both are prime.
pairs = []
# q must be less than 400
for q in range(2, 400):
    if is_prime(q):
        r = 800 - q
        if r > q and is_prime(r):
            pairs.append((q, r))

print("Prime pairs (q, r) summing to 800 (q < r):")
for pair in pairs:
    print(pair)

# We proceed to check the constraints for each pair.
results = []
for q, r in pairs:
    # Iterate over possible primes p such that p < q
    for p in range(2, q):
        if is_prime(p):
            # Check the four constraints:
            # 1. A = p + q - r
            A = p + q - r
            # 2. B = q + r - p = 800 - p
            B = 800 - p
            # 3. C = r + p - q
            C = r + p - q
            # 4. D = p + q + r = 800 + p
            D = 800 + p

            if is_prime(A) and is_prime(B) and is_prime(C) and is_prime(D):
                results.append((p, q, r))

print("\nValid triples (p, q, r) for Case 2 (q+r=800):")
for res in results:
    print(res)

if results:
    max_r = max(r for p, q, r in results)
    print(f"\nMaximum r found: {max_r}")
else:
    print("\nNo valid triples found for Case 2.")

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

prime_pairs = []
# Since p+r=800, both p and r must be odd primes (or p=2, which gives r=798, not prime).
# p must be less than 400.
for p in range(3, 400, 2):
    if is_prime(p):
        r = 800 - p
        if is_prime(r):
            prime_pairs.append((p, r))

print(f"Prime pairs (p, r) where p+r=800: {prime_pairs}")

# Identify the pair with the maximum r
max_r = -1
max_pair = None
for p, r in prime_pairs:
    if r > max_r:
        max_r = r
        max_pair = (p, r)

print(f"Maximum r candidate: {max_r} (from pair {max_pair})")

